/**
 * Form lifecycle modeled as a discriminated union.
 *
 * Every state carries a `status` discriminant, so narrowing is exhaustive
 * and the compiler knows exactly which fields exist in each branch.
 */

export interface Values {
  readonly [field: string]: string;
}

export type FormState =
  | { status: 'editing'; values: Values; errors: Readonly<Record<string, string>> }
  | { status: 'submitting'; values: Values }
  | { status: 'succeeded'; result: string }
  | { status: 'failed'; values: Values; error: string; attempt: number };

export type FormEvent =
  | { type: 'CHANGE'; field: string; value: string }
  | { type: 'SUBMIT' }
  | { type: 'RESOLVE'; result: string }
  | { type: 'REJECT'; error: string }
  | { type: 'RETRY' }
  | { type: 'EDIT_AGAIN' };

const EMPTY_ERRORS: Readonly<Record<string, string>> = {};

/** Entry point of the lifecycle. */
export function initialForm(values: Values = {}): FormState {
  return { status: 'editing', values, errors: EMPTY_ERRORS };
}

/**
 * Pure reducer. Legal transitions return a new state; illegal pairs return
 * the *same* state object unchanged, making no-ops trivially detectable
 * via reference equality.
 */
export function transition(state: FormState, event: FormEvent): FormState {
  switch (state.status) {
    case 'editing':
      switch (event.type) {
        case 'CHANGE': {
          const { [event.field]: _replaced, ...rest } = state.errors;
          const errors =
            event.value === ''
              ? { ...rest, [event.field]: 'required' }
              : rest;
          return {
            status: 'editing',
            values: { ...state.values, [event.field]: event.value },
            errors,
          };
        }
        case 'SUBMIT':
          return { status: 'submitting', values: { ...state.values } };
        default:
          // CHANGE/SUBMIT handled above; anything else is illegal for editing.
          break;
      }
      break;

    case 'submitting':
      switch (event.type) {
        case 'RESOLVE':
          return { status: 'succeeded', result: event.result };
        case 'REJECT':
          return {
            status: 'failed',
            values: { ...state.values },
            error: event.error,
            attempt: 1,
          };
        default:
          // e.g. CHANGE while submitting: ignored by design.
          break;
      }
      break;

    case 'succeeded':
      switch (event.type) {
        case 'EDIT_AGAIN':
          return { status: 'editing', values: {}, errors: EMPTY_ERRORS };
        default:
          break;
      }
      break;

    case 'failed':
      switch (event.type) {
        case 'RETRY':
          return { status: 'submitting', values: { ...state.values }, ...(void 0) };
        case 'EDIT_AGAIN':
          return { status: 'editing', values: { ...state.values }, errors: EMPTY_ERRORS };
        default:
          break;
      }
      break;

    default: {
      // If a new member is ever added to FormState and not handled above,
      // this assignment fails to compile — exhaustiveness enforced locally.
      const _exhaustive: never = state;
      void _exhaustive;
    }
  }

  // Illegal event/status pair (or unknown event): no-op.
  return state;
}

