import { describe, it, expectTypeOf } from 'vitest';
import { transition, initialForm, type FormState } from '../src/state.js';

describe('type-level guarantees', () => {
  it('narrowing by status exposes only the declared fields', () => {
    const state: FormState = initialForm();

    if (state.status === 'submitting') {
      // Reading `errors` (or `error`/`attempt`/`result`) off a submitting
      // state must not compile. Each @ts-expect-error proves the union is
      // properly discriminated: the submitting branch simply has no such key.
      // @ts-expect-error - `errors` does not exist on the submitting branch
      expectTypeOf(state.errors).toBeUndefined();
      // @ts-expect-error - `error` does not exist on the submitting branch
      state.error;
      // @ts-expect-error - `attempt` does not exist on the submitting branch
      state.attempt;
      // @ts-expect-error - `result` does not exist on the submitting branch
      state.result;
      expectTypeOf(state.values).toEqualTypeOf<Record<string, string>>();
    }

    if (state.status === 'succeeded') {
      expectTypeOf(state.result).toBeString();
      // @ts-expect-error - `values` does not exist on the succeeded branch
      state.values;
    }

    if (state.status === 'failed') {
      expectTypeOf(state.attempt).toBeNumber();
      expectTypeOf(state.error).toBeString();
      // @ts-expect-error - `errors` does not exist on the failed branch
      state.errors;
    }
  });

  it('transition never widens away from FormState', () => {
    const state: FormState = initialForm();
    expectTypeOf(transition(state, { type: 'SUBMIT' })).not.toBeNever();
  });
});

