import { describe, it, expect } from 'vitest';
import { transition, initialForm, type FormState } from '../src/state.js';

const EDITING = () => initialForm({ email: '' });
const SUBMITTING = (values: Record<string, string> = {}) =>
  transition(initialForm(values), { type: 'SUBMIT' });

describe('legal transitions', () => {
  it('CHANGE while editing updates values and clears the field error', () => {
    const s0 = transition(EDITING(), { type: 'CHANGE', field: 'email', value: 'x' });
    expect(s0).toEqual({ status: 'editing', values: { email: 'x' }, errors: {} });

    // Emptying a required field records an error.
    const s1 = transition(s0, { type: 'CHANGE', field: 'email', value: '' });
    expect(s1).toEqual({
      status: 'editing',
      values: { email: '' },
      errors: { email: 'required' },
    });
  });

  it('SUBMIT while editing moves to submitting with the same values', () => {
    expect(SUBMITTING({ email: 'a@b.c' })).toEqual({
      status: 'submitting',
      values: { email: 'a@b.c' },
    });
  });

  it('RESOLVE while submitting moves to succeeded with the result', () => {
    expect(
      transition(SUBMITTING(), { type: 'RESOLVE', result: 'created #42' }),
    ).toEqual({ status: 'succeeded', result: 'created #42' });
  });

  it('REJECT while submitting moves to failed with attempt = 1', () => {
    const failed = transition(SUBMITTING({ a: '1' }), {
      type: 'REJECT',
      error: '500',
    });
    expect(failed).toEqual({
      status: 'failed',
      values: { a: '1' },
      error: '500',
      attempt: 1,
    });
  });

  it('RETRY while failed goes back to submitting', () => {
    const failed: FormState = transition(SUBMITTING(), {
      type: 'REJECT',
      error: 'timeout',
    });
    expect(transition(failed, { type: 'RETRY' })).toEqual({
      status: 'submitting',
      values: {},
    });
  });

  it('EDIT_AGAIN while failed returns to editing with prior values restored', () => {
    const failed = transition(SUBMITTING({ email: 'a@b.c' }), {
      type: 'REJECT',
      error: '400',
    });
    expect(transition(failed, { type: 'EDIT_AGAIN' })).toEqual({
      status: 'editing',
      values: { email: 'a@b.c' },
      errors: {},
    });
  });

  it('EDIT_AGAIN after success starts a fresh edit session', () => {
    const ok: FormState = { status: 'succeeded', result: 'ok' };
    expect(transition(ok, { type: 'EDIT_AGAIN' })).toEqual({
      status: 'editing',
      values: {},
      errors: {},
    });
  });

  it('the reducer is pure: inputs are never mutated', () => {
    const s0 = EDITING();
    const s1 = transition(s0, { type: 'CHANGE', field: 'email', value: 'z' });
    expect(s0.values.email).toBe('');
    expect(s1).not.toBe(s0);
  });
});

describe('illegal transitions are ignored (state returned unchanged)', () => {
  it('CHANGE while submitting is ignored', () => {
    const submitting = SUBMITTING();
    expect(transition(submitting, { type: 'CHANGE', field: 'a', value: 'b' })).toBe(
      submitting,
    );
  });

  it('RETRY while editing is ignored', () => {
    const editing = EDITING();
    expect(transition(editing, { type: 'RETRY' })).toBe(editing);
  });

  it('SUBMIT while submitting is ignored (no double submit)', () => {
    const submitting = SUBMITTING();
    expect(transition(submitting, { type: 'SUBMIT' })).toBe(submitting);
  });

  it('SUBMIT/RETRY/etc. on a terminal state are ignored', () => {
    const ok: FormState = { status: 'succeeded', result: 'done' };
    for (const event of [
      { type: 'SUBMIT' },
      { type: 'RETRY' },
      { type: 'CHANGE', field: 'a', value: 'b' },
      { type: 'RESOLVE', result: 'x' },
      { type: 'REJECT', error: 'y' },
    ] as const) {
      if (event.type === 'EDIT_AGAIN') continue; // legal; covered elsewhere
      expect(transition(ok, event)).toBe(ok);
    }

    const failed = transition(SUBMITTING(), { type: 'REJECT', error: 'e' });
    expect(
      transition(failed, { type: 'CHANGE', field: 'a', value: 'b' }),
    ).toBe(failed);
    expect(transition(failed, { type: 'SUBMIT' })).toBe(failed);
    expect(transition(failed, { type: 'RESOLVE', result: 'r' })).toBe(failed);
    expect(transition(failed, { type: 'REJECT', error: 'e2' })).toBe(failed);
  });

  it('RESOLVE/REJECT while editing is ignored', () => {
    const editing = EDITING();
    expect(transition(editing, { type: 'RESOLVE', result: 'r' })).toBe(editing);
    expect(transition(editing, { type: 'REJECT', error: 'e' })).toBe(editing);
  });
});

